PrCssUnit cssUnitFromText(PrStringView text) {
    uint64_t word;
    uint64_t hash = nameHashLower(text.data, text.size, 0xc5a49d04a6bab236ull, &word);
    uint32_t unit = kCssUnitSlot[(uint32_t(hash)
        + kCssUnitDisplace[(hash >> 32) & 63u] * (uint32_t(hash >> 32) | 1))
        & 63u];
    return nameEqualsLower(nameAt(kCssUnitBlob, kCssUnitAt, unit), text, word)
        ? PrCssUnit(PrCssUnit_Em + unit) : PrCssUnit_Unknown;
}

PrStringView cssUnitName(PrCssUnit unit) {
    return kCssUnitSpelling[unit - PrCssUnit_Em];
}

CssUnitCategory cssUnitCategory(PrCssUnit unit) {
    if (unit == PrCssUnit_Number)
        return CssUnitCategory_Number;
    if (unit < PrCssUnit_Em || unit >= PrCssUnit_Unknown)
        return CssUnitCategory_Unknown;
    return kCssUnitCategory[unit - PrCssUnit_Em];
}

double cssUnitScale(PrCssUnit unit) {
    if (unit < PrCssUnit_Em || unit >= PrCssUnit_Unknown)
        return 0;
    return kCssUnitScale[unit - PrCssUnit_Em];
}

PrCssUnit cssUnitCanonical(CssUnitCategory category) {
    return kCssUnitCanonical[category];
}

bool cssUnitViewportRelative(PrCssUnit unit) {
    return unit >= PrCssUnit_Vw && unit <= PrCssUnit_Dvmax;
}

